class TerminalController:

    def __init__(self, owner) -> None:
        self.owner = owner
        self.executions: dict[str, TerminalExecution] = {}
        self.state = OpenTerminalControllerState()
        self._next_id = 0

    async def create(self, command: Command, output_byte_limit: int | None) -> str:
        state = self.state
        state.require_create()
        self._next_id += 1
        terminal_id = f'terminal-{self._next_id}'
        execution = TerminalExecution(command, output_byte_limit)
        self.executions[terminal_id] = execution
        self.owner.surface.prepare_terminal(execution.state)
        try:
            await execution.start()
            if self.state is state:
                self.owner.surface.publish_terminal(self, terminal_id, execution)
            if self.state is not state:
                raise TerminalSessionRetired('ACP terminal session retired during creation')
            return terminal_id
        except BaseException as error:
            await self.retire(terminal_id)
            if self.state is not state:
                raise TerminalSessionRetired('ACP terminal session retired during creation') from error
            raise

    async def attach(self, binding) -> None:
        if self.owner.surface is not binding:
            return
        for terminal_id, execution in tuple(self.executions.items()):
            binding.publish_terminal(self, terminal_id, execution)

    def owns_projection(self, terminal_id, execution):
        return self.state.owns_projection(self.executions, terminal_id, execution)

    def detach(self) -> None:
        for execution in self.executions.values():
            execution.detach()

    def require(self, terminal_id: str) -> TerminalExecution:
        return self.executions[terminal_id]

    def output(self, terminal_id: str) -> ToolState:
        return self.require(terminal_id).tool_state

    async def wait(self, terminal_id: str):
        return await self.require(terminal_id).wait_for_exit()

    def kill(self, terminal_id: str) -> None:
        self.require(terminal_id).kill()

    async def release(self, terminal_id: str) -> None:
        execution = self.require(terminal_id)
        await join_retirement(asyncio.create_task(self._release(terminal_id, execution)))

    async def _release(self, terminal_id, execution):
        await execution.close()
        self.executions.pop(terminal_id, None)

    async def retire(self, terminal_id) -> None:
        execution = self.executions.get(terminal_id)
        if execution is not None:
            await join_retirement(asyncio.create_task(self._release(terminal_id, execution)))

    async def close(self) -> None:
        self.state = RetiredTerminalControllerState()
        self.detach()
        await join_retirement(asyncio.create_task(self._close()))

    async def _close(self):
        for terminal_id, execution in tuple(self.executions.items()):
            await self._release(terminal_id, execution)

class ShellTerminalOutput(ShellOutput):
    """The original ANSI state survives; a Terminal only projects that state."""

    def __init__(self, state: ansi.TerminalState) -> None:
        self.state = state
        self.finalized = False
        self.terminal: 'Terminal | None' = None

    async def present(self, conversation: 'Conversation') -> None:
        if self.terminal is not None:
            return
        terminal = await conversation.new_terminal()
        self.terminal = terminal
        terminal.set_state(self.state)
        terminal.update_size(terminal.width, terminal.height)
        terminal.set_write_to_stdin(self.state.write_stdin)
        terminal.project_state(None, None)
        if self.finalized:
            terminal.finalize()

    def project(self, scrollback: set[int] | None, alternate: set[int] | None) -> None:
        if self.terminal is not None:
            self.terminal.project_state(scrollback, alternate)
            if self.finalized:
                self.terminal.finalize()

    def focus(self) -> None:
        if self.terminal is not None:
            self.terminal.focus(scroll_visible=False)

    def finalize(self) -> None:
        self.finalized = True
        self.state.show_cursor = False
        self.project(None, None)

    def detach(self) -> None:
        self.terminal = None

class TerminalExecution:
    """One ANSI/output owner and one acquired operation, independent of views."""

    def __init__(self, command: Command, output_byte_limit: int | None=None, *, width: int=ansi.TerminalState.DEFAULT_WIDTH, height: int=ansi.TerminalState.DEFAULT_HEIGHT):
        self._command = command
        self._output_byte_limit = output_byte_limit
        self._output: deque[bytes] = deque()
        self._bytes_read = 0
        self._output_bytes_count = 0
        self._operation: TerminalOperation = NewTerminalOperation()
        self.state = ansi.TerminalState(self.write_stdin, width=width, height=height)
        self._view = lambda: None

    @property
    def command(self):
        return self._command

    @property
    def outcome(self):
        return self._operation.outcome()

    @property
    def tool_state(self):
        output, truncated = self.get_output()
        return ToolState(output, truncated, self.outcome)

    def attach(self, terminal):
        self._view = ref(terminal)
        terminal.set_state(self.state)
        terminal.set_write_to_stdin(self.write_stdin)
        self.project()

    def detach(self, terminal=None):
        if terminal is None or self._view() is terminal:
            self._view = lambda: None

    def project(self):
        if (terminal := self._view()) is not None and terminal.is_attached:
            terminal.present_execution()

    def update_size(self, width, height):
        self.state.update_size(width, height)
        self._operation.resize(width, height)

    async def close(self):
        self.detach()
        self._operation = self._operation.retire()
        await self._operation.close()

    def kill(self) -> None:
        self._operation.kill()

    async def wait_for_exit(self):
        return await self._operation.wait()

    async def custody(self) -> PtyProcess:
        """Observe the SAME original acquired resource, never a copied PID/status."""
        return await self._operation.custody()

    async def start(self):
        operation = self._operation.start(self)
        self._operation = operation
        await asyncio.shield(operation.ready)

    async def run(self, ready):
        try:
            async with AsyncExitStack() as custody:
                master, slave = pty.openpty()
                master_file = custody.enter_context(os.fdopen(master, 'rb', 0))
                slave_file = custody.enter_context(os.fdopen(slave, 'wb', 0))
                flags = fcntl.fcntl(master, fcntl.F_GETFL)
                fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
                command = self.command
                run_command = command.command if ' ' in command.command else f'{command.command} {shlex.join(command.args)}'
                shell_command = (os.environ.get('SHELL', 'sh'), '-c', run_command)
                spawn = asyncio.create_task(PtyProcess.acquire(command, shell_command, master_file, slave_file, custody, self.state))
                try:
                    acquired = await asyncio.shield(spawn)
                except asyncio.CancelledError:
                    await join_retirement(spawn)
                    raise
                slave_file.close()
                reader = asyncio.StreamReader(128 * 1024)
                protocol = asyncio.StreamReaderProtocol(reader)
                transport, _ = await asyncio.get_running_loop().connect_read_pipe(lambda: protocol, master_file)
                custody.callback(transport.close)
                ready.set_result(acquired)
                decoder = codecs.getincrementaldecoder('utf-8')(errors='replace')
                while True:
                    data = await shell_read(reader, 128 * 1024)
                    self._record_output(data)
                    if (decoded := decoder.decode(data, final=not data)):
                        await self.state.write(decoded)
                        self.project()
                    if not data:
                        break
                return TerminalCompletion.capture(await acquired.child.wait())
        except BaseException as error:
            if not ready.done():
                ready.set_exception(error)
            raise
        finally:
            self.state.show_cursor = False
            asyncio.get_running_loop().call_soon(self.project)

    async def write_stdin(self, text: str | bytes, hide_echo=False):
        data = text.encode('utf-8', 'ignore') if isinstance(text, str) else text
        return await self._operation.write(data)

    def _record_output(self, data: bytes) -> None:
        """Keep a record of the bytes left.

        Store at most the limit set in self._output_byte_limit (if set).

        """
        self._output.append(data)
        self._output_bytes_count += len(data)
        self._bytes_read += len(data)
        if self._output_byte_limit is None:
            return
        while self._output_bytes_count > self._output_byte_limit and self._output:
            oldest_bytes = self._output[0]
            oldest_bytes_count = len(oldest_bytes)
            if self._output_bytes_count - oldest_bytes_count < self._output_byte_limit:
                break
            self._output.popleft()
            self._output_bytes_count -= oldest_bytes_count

    def get_output(self) -> tuple[str, bool]:
        """Get the output.

        Returns:
            A tuple of the output and a bool to indicate if the output was truncated.
        """
        output_bytes = b''.join(self._output)

        def is_continuation(byte_value: int) -> bool:
            """Check if the given byte is a utf-8 continuation byte.

            Args:
                byte_value: Ordinal of the byte.

            Returns:
                `True` if the byte is a continuation, or `False` if it is the start of a character.
            """
            return byte_value & 192 == 128
        truncated = self._bytes_read > len(output_bytes)
        if self._output_byte_limit is not None and len(output_bytes) > self._output_byte_limit:
            truncated = True
            output_bytes = output_bytes[len(output_bytes) - self._output_byte_limit:]
            for offset, byte_value in enumerate(output_bytes):
                if not is_continuation(byte_value):
                    if offset:
                        output_bytes = output_bytes[offset:]
                    break
            else:
                output_bytes = b''
        output = output_bytes.decode('utf-8', 'replace')
        return (output, truncated)

class TerminalStateProjection:

    def project_state(self, scrollback_delta: set[int] | None, alternate_delta: set[int] | None) -> None:
        """Paint the owning ANSI state without decoding or replaying output."""
        self._update_from_state(scrollback_delta, alternate_delta)
        self.display = self.state.alternate_screen or not self.state.scrollback_buffer.is_blank
        if self._alternate_screen != self.state.alternate_screen:
            self.post_message(self.AlternateScreenChanged(self, enabled=self.state.alternate_screen))
        self._alternate_screen = self.state.alternate_screen

    def _update_from_state(self, scrollback_delta: set[int] | None, alternate_delta: set[int] | None) -> None:
        if self.state.current_directory:
            self.current_directory = self.state.current_directory
            self.finalize()
        width = self.state.width
        height = self.state.scrollback_buffer.height
        if self.state.alternate_screen:
            height += self.state.alternate_buffer.height
        self.virtual_size = Size(min(self.state.buffer.max_line_width, width), height)
        if self._anchored and (not self._anchor_released):
            self.scroll_y = self.max_scroll_y
        scroll_y = int(self.scroll_y)
        visible_lines = frozenset(range(scroll_y, scroll_y + height))
        if scrollback_delta is None and alternate_delta is None:
            self.refresh()
        else:
            window_width = self.region.width
            scrollback_height = self.state.scrollback_buffer.height
            if scrollback_delta is None:
                self.refresh(Region(0, 0, window_width, scrollback_height))
            else:
                refresh_lines = [Region(0, y - scroll_y, window_width, 1) for y in sorted(scrollback_delta & visible_lines)]
                if refresh_lines:
                    self.refresh(*refresh_lines)
            alternate_height = self.state.alternate_buffer.height
            if alternate_delta is None:
                self.refresh(Region(0, scrollback_height - scroll_y, window_width, scrollback_height + alternate_height))
            else:
                alternate_delta = {line_no + scrollback_height for line_no in alternate_delta}
                refresh_lines = [Region(0, y - scroll_y, window_width, 1) for y in sorted(alternate_delta & visible_lines)]
                if refresh_lines:
                    self.refresh(*refresh_lines)

class TerminalTool(Terminal, MroDispatch):

    @dataclass
    class Projection(Message):
        """A native render request borrows its original acquired resources."""
        binding: AttachedSurfaceBinding
        controller: TerminalController
        terminal_id: str
        execution: TerminalExecution
    DEFAULT_CSS = '\n    TerminalTool {\n        height: auto;\n        border: panel $text-primary;\n    }\n    '

    def __init__(self, execution: TerminalExecution, *, id: str) -> None:
        self.execution = execution
        super().__init__(id=id, size=(execution.state.width, execution.state.height))
        self.border_title = Content(str(execution.command))

    def on_mount(self) -> None:
        super().on_mount()
        self.execution.attach(self)

    def on_unmount(self) -> None:
        self.execution.detach(self)

    def resize_process(self, width: int, height: int) -> None:
        self.execution.update_size(width, height)

    def present_execution(self) -> None:
        self.project_state(None, None)
        self.dispatch_sync(self.execution.outcome)

    @handles(RunningTerminalOutcome, UnstartedTerminalOutcome, RetiredTerminalOutcome)
    def present_pending(self, outcome) -> None:
        """These original outcomes have no completion border to draw."""

    @handles(TerminalCompletion)
    def present_completion(self, outcome) -> None:
        self.finalize()
        self.set_class(outcome.successful, '-success')
        self.set_class(not outcome.successful, '-error')
        if not outcome.successful:
            self.border_title = Content(f'{self.execution.command} [{outcome.label}]')

    @handles(FailedTerminalOutcome)
    def present_failure(self, outcome) -> None:
        self.finalize()
        self.set_class(True, '-error')
        self.border_title = Content(f'{self.execution.command} [{outcome.error}]')
